// Option A: custom deserializer for backward compatibility
impl<'de> Deserialize<'de> for TaskKind {
    fn deserialize<D>(deserializer: D) -> Result<Self, D::Error>
    where
        D: serde::Deserializer<'de>,
    {
        let s = String::deserialize(deserializer)?;
        match s.as_str() {
            "milestone" => Ok(TaskKind::Milestone),
            "feature" => Ok(TaskKind::Feature),
            "bug" => Ok(TaskKind::Bug),
            "task" => Ok(TaskKind::Task),
            "chore" => Ok(TaskKind::Chore),
            "spike" => Ok(TaskKind::Spike),
            "decision" => Ok(TaskKind::Decision),
            // Backward-compatible aliases for removed variants
            "dep" | "template" => Ok(TaskKind::Task),
            other => Err(serde::de::Error::unknown_variant(other, &[
                "milestone", "feature", "bug", "task", "chore", "spike", "decision",
            ])),
        }
    }
}

